insert into achievements (title,description,image_url,category,year) values ('الفوز بعضوية مجلس النواب العراقي','فاز في انتخابات 2025 بـ 13,804 صوتاً عن قائمة «نينوى لأهلها» ممثلاً لمحافظة نينوى.','/img/rakan.jpg','الانتخابات',2025);
insert into achievements (title,description,image_url,category,year) values ('عضوية لجنة النزاهة النيابية','اختاره مجلس النواب عضواً في لجنة النزاهة النيابية للمساهمة في الرقابة ومكافحة الفساد.','/img/interview.jpg','العمل النيابي',2025);
insert into achievements (title,description,image_url,category,year) values ('متابعة وإنجاز معاملات المواطنين لدى الوزارات','وجبات متتالية من الموافقات والمعاملات المنجزة لأهالي نينوى في وزارات العمل والشؤون الاجتماعية والصحة والتربية والعدل والداخلية (الرعاية الاجتماعية، المعين المتفرغ، ذوو الاحتياجات الخاصة وغيرها)، تُعلن أولاً بأول على القناة الرسمية في تلغرام.','/img/rakan.jpg','خدمة المواطنين',2026);
insert into achievements (title,description,image_url,category,year) values ('تبنّي مطالب الشرائح الوظيفية والأمنية','تبنّى مطالب خريجي قناة النخبة، وإعادة فتح منظومة الكودات، وإنصاف احتياط النجاح للدورة 72 لكليتي الشرطة، وغيرها.','/img/rakan.jpg','العمل النيابي',2026);
insert into achievements (title,description,image_url,category,year) values ('متابعة ميدانية للملفات الأمنية والخدمية','زيارات متواصلة لمديرية مكافحة الإجرام والأمن الوطني وقيادة شرطة نينوى لبحث الملفات الأمنية وتعزيز التنسيق، ولقاء مدير تربية الحدباء لمتابعة احتياجات القطاع التربوي.','/img/news/Dd1YYlxGZyq.jpg','العمل الميداني',2026);
